P = [
 dict(pmid='', doi='10.5194/acp-26-16477-2026', journal='Atmospheric Chemistry and Physics', title='Molecular composition of wintertime haze over the northern Indian Ocean suggests extensive atmospheric processing during transport', tier='B', basis='Lab / research instrument', short='Maldives Climate Observatory winter haze by AMS + FIGAERO-CIMS: uniform, sulfate ~48% of NR-PM1, highly oxygenated OA, 18 S-organics', design='Measurement campaign', pm='Aerosol mass spectrometer non-refractory PM1 and FIGAERO-CIMS molecular composition at a receptor site', geo='Indo-Pacific', endpoint='Molecular composition and atmospheric processing of submicron outflow aerosol', affil='not stated; Stockholm University, Sweden', n='Winter high-time-resolution measurements at the Maldives Climate Observatory, Hanimaadhoo, with an aerosol mass spectrometer and FIGAERO-CIMS, characterising the South Asian outflow haze at molecular level. Composition was remarkably uniform despite varying source regions and loading, indicating strong regional mixing; sulfate was about 48% of non-refractory submicron mass; 18 sulfur-containing organics were identified, some for the first time at this site; organic aerosol was highly oxygenated with prominent dicarboxylic acids. Weakness: one receptor site and season, no quantitative source apportionment in the abstract, and FIGAERO-CIMS sensitivities for many species are uncertain. Relevance: indirect - aged, sulfate-dominated, highly hygroscopic outflow is the aerosol for which humidity corrections derived over land will bias optical sensors.', sub=corpus.EXPO),
 dict(pmid='', doi='10.5194/acp-26-16501-2026', journal='Atmospheric Chemistry and Physics', title='Measurement report: Tethered balloon observations of vertically resolved aerosol size distributions during the U.S. DOE ARM CoURAGE and BNF campaigns', tier='B', basis='Lab / research instrument', short='ARM tethered balloon with miniature SEMS: 63 vertical size-distribution profiles (10-300 nm); NPF particles stored in residual layer overnight', design='Measurement campaign', pm='Miniature scanning electrical mobility spectrometer on the DOE ARM tethered balloon, 10-300 nm number size distributions to ~1200 m', geo='USA', endpoint='Vertical structure of aerosol number size distribution in and above the boundary layer', affil='not stated; University at Albany, State University of New York, USA', n='A miniature scanning electrical mobility spectrometer flew on the DOE ARM tethered balloon during the 2025 CoURAGE and Bankhead National Forest campaigns, yielding 63 particle number size-distribution profiles (10-300 nm) from the surface to about 1,200 m. Profiles were homogeneous under efficient boundary-layer mixing and layered under incomplete mixing or elevated plumes; above the boundary layer they resolved transitions into the free troposphere and nocturnal residual layer. On 27 March 2025, new-particle-formation products were preserved overnight in the residual layer and mixed down the next morning. Weakness: number not mass, a 10-300 nm window, and tethered operation limited by weather. Relevance: residual-layer mixing-down explains morning surface jumps that ground networks and their ML forecasts tend to attribute to local sources.', sub=corpus.SENS),
 dict(pmid='43056051', doi='10.1007/s11356-026-38425-0', journal='Environ Sci Pollut Res Int', title='Physicochemical evolution of transported mineral dust over northern China: evidence from field sampling and laboratory analysis during haze episodes.', tier='C', basis='Lab / research instrument', short='Spring 2022 Asian dust over northern China: coarse dust acquires sulfate/nitrate coatings and acts as a multiphase reactor (qualitative)', design='Laboratory + field measurement', pm='Transported coarse mineral dust sampled during dust events; bulk composition, FE-SEM single-particle morphology, ion chromatography', geo='China (northern)', endpoint='Physicochemical ageing of dust: secondary coatings, morphology, catalytic metal content', affil='Southwest University of Science and Technology, China; Southwest University of Science and Technology, China', n='Field sampling during spring 2022 Asian dust events over northern China with laboratory analyses: source apportionment, bulk composition, FE-SEM single-particle imaging and ion chromatography. Coarse dust carried reactive calcite and clay frameworks and Fe and Mn; individual particles acquired secondary coatings dominated by sulfate and nitrate, which the authors interpret as dust acting as a multiphase reactor for heterogeneous SO2 and NOx oxidation rather than contributing directly to fine PM. Weakness: the abstract reports no quantities (coating fractions, uptake coefficients, sample numbers), so the oxidation-capacity claim is qualitative and inferred from composition, not measured kinetics. Relevance: coated, hygroscopic coarse dust is where optical low-cost sensors err most - undercounting coarse mass while humidity growth inflates readings.', sub=corpus.EXPO),
 dict(pmid='43048109', doi='10.1021/acsestair.6c00206', journal='ACS ES&T air', title='Influence of Nonpolar Amino Acids on Phase Transitions of Atmospheric Aerosol Particles.', tier='C', basis='Lab / research instrument', short='Nonpolar amino acids lower separation RH and can crystallise into three-phase particles in ammonium sulfate/organic droplets', design='Laboratory measurement', pm='Ternary droplets of ammonium sulfate, a nonpolar amino acid and 2-methylglutaric acid or 1,2,6-hexanetriol; optical and Raman microscopy', geo='Laboratory (no field site)', endpoint='Separation and efflorescence relative humidity, morphology and phase state', affil='Pennsylvania State University, USA; Pennsylvania State University, USA', n='Optical and Raman microscopy of ternary droplets of ammonium sulfate, a nonpolar amino acid and a model oxidised organic (2-methylglutaric acid or 1,2,6-hexanetriol). Raising the amino-acid fraction of the organic component lowered the separation relative humidity; in some systems the amino acid crystallised while the organic and ammonium sulfate underwent liquid-liquid phase separation, giving three phases. Efflorescence RH trends followed amino-acid solubility. Weakness: model mixtures on substrates, a narrow compound set and no numbers in the abstract; ambient organonitrogen is far more diverse. Relevance: phase state and efflorescence set the hysteresis of hygroscopic growth, which governs humidity correction of optical PM sensors; organonitrogen-rich aerosol may shift that hysteresis.', sub=corpus.EXPO),
]
